import {backend} from './backend.js';
import {escape as e} from './store.js';
let content={mission:'',founders:[],contributors:[],support:{email:'',phone:''}},error='',draft=[];
export function safePortrait(value){try{const url=new URL(value);return url.protocol==='https:'?url.href:'';}catch{return '';}}
export const photoPosition=value=>Number.isFinite(Number(value))?Math.max(0,Math.min(100,Number(value))):50;
export function normalizeAbout(value={}){return {support:{email:String(value.support?.email||'').slice(0,254),phone:String(value.support?.phone||'').slice(0,30)},mission:String(value.mission||'').slice(0,12000),founders:Array.isArray(value.founders)?value.founders.slice(0,20).filter(x=>x&&typeof x.name==='string').map(x=>({name:x.name.slice(0,120),bio:String(x.bio||'').slice(0,4000),photo:safePortrait(x.photo),x:photoPosition(x.x??50),y:photoPosition(x.y??50),fit:x.fit==='contain'?'contain':'cover'})):[],contributors:Array.isArray(value.contributors)?value.contributors.filter(x=>typeof x==='string').slice(0,200).map(x=>x.slice(0,300)):[]};}
export async function loadAbout(){try{const rows=await backend.read('lexamah_about');content=normalizeAbout(rows?.[0]?.content);error='';}catch{error='Run supabase/about.sql in SQL Editor to enable editing this page.';}return content;}
export function aboutPage(){return `<div class="heading"><div><span class="eyebrow">THE PEOPLE AND PURPOSE</span><h1>About LexAmah</h1><p>Meet the people behind your legal learning workspace.</p></div></div><section class="card mission-card"><span class="eyebrow">WHY WE CREATED LEXAMAH</span><h2>Our Mission</h2><p class="mission-copy">${e(content.mission||'Our mission will be shared here soon.')}</p></section><div class="section-title"><h2>Meet the Founders</h2></div><div class="grid">${content.founders.length?content.founders.map(founder=>`<article class="card founder-card">${founder.photo?`<img src="${e(founder.photo)}" alt="${e(founder.name)}" style="object-fit:${founder.fit};object-position:${founder.x}% ${founder.y}%" loading="lazy" referrerpolicy="no-referrer">`:`<div class="founder-initial">${e(founder.name.charAt(0))}</div>`}<h3>${e(founder.name)}</h3><p>${e(founder.bio)}</p></article>`).join(''):'<p class="muted">Founder profiles will be added soon.</p>'}</div><section class="card" style="margin-top:28px"><div class="card-head"><h2>Our Contributors</h2></div>${content.contributors.length?`<ul class="contributors-list">${content.contributors.map(name=>`<li>${e(name)}</li>`).join('')}</ul>`:'<p class="muted">We look forward to recognizing everyone who contributes to LexAmah.</p>'}</section>${supportSection()}`;}
function founderFields(){return draft.map((founder,i)=>`<section class="card" style="margin:15px 0"><div class="card-head"><h3>Founder ${i+1}</h3><button class="btn danger" type="button" data-remove-founder="${i}">Remove profile</button></div><label for="founder-name-${i}">Full name</label><input id="founder-name-${i}" name="founder-name-${i}" required maxlength="120" value="${e(founder.name)}"><label for="founder-bio-${i}">Bio</label><textarea id="founder-bio-${i}" name="founder-bio-${i}" maxlength="4000">${e(founder.bio)}</textarea><label for="founder-photo-${i}">Picture URL (optional)</label><input id="founder-photo-${i}" name="founder-photo-${i}" type="url" value="${e(founder.photo)}" placeholder="https://…"><label for="founder-file-${i}">Or upload a picture</label><input id="founder-file-${i}" name="founder-file-${i}" type="file" accept=".jpg,.jpeg,.png,.webp"><p class="muted">JPG, PNG or WebP, up to 5 MB. Uploading replaces the picture URL.</p><img id="founder-preview-${i}" class="portrait-preview ${founder.photo?'':'hidden'}" ${founder.photo?`src="${e(founder.photo)}"`:''} alt="Picture preview" style="object-fit:${founder.fit||'cover'};object-position:${founder.x??50}% ${founder.y??50}%"><label for="founder-fit-${i}">Picture display</label><select id="founder-fit-${i}"><option value="cover" ${founder.fit!=='contain'?'selected':''}>Fill frame — adjust face position below</option><option value="contain" ${founder.fit==='contain'?'selected':''}>Show whole picture</option></select><label for="founder-x-${i}">Horizontal position</label><input id="founder-x-${i}" type="range" min="0" max="100" value="${founder.x??50}"><label for="founder-y-${i}">Vertical position</label><input id="founder-y-${i}" type="range" min="0" max="100" value="${founder.y??50}"></section>`).join('');}
export function aboutEditor(){draft=structuredClone(content.founders);return `<section class="card"><div class="card-head"><h2>About LexAmah</h2><span class="pill">Public page</span></div>${error?`<div class="notice">${e(error)}</div>`:`<form id="about-form"><label for="about-mission">Our Mission — why we created the platform</label><textarea id="about-mission" name="mission" rows="6" maxlength="12000">${e(content.mission)}</textarea><div class="section-title"><h2>Founders</h2><button class="btn" type="button" id="add-founder">+ Add founder</button></div><div id="founder-fields">${founderFields()}</div><label for="about-contributors">Contributors — one name or name and contribution per line</label><textarea id="about-contributors" name="contributors" rows="6">${e(content.contributors.join('\n'))}</textarea><label for="support-email">Contact/support email</label><input id="support-email" type="email" maxlength="254" value="${e(content.support.email)}" placeholder="support@example.com"><label for="support-phone">Contact/support phone</label><input id="support-phone" type="tel" maxlength="30" value="${e(content.support.phone)}" placeholder="+234…"><p id="about-status" class="muted" role="status"></p><div class="actions"><button class="btn primary" id="about-save">Publish changes</button><button class="btn" type="button" data-route="about">View public page</button></div></form>`}</section>`;}
export function bindAboutEditor(ui){const form=document.querySelector('#about-form');if(!form)return;const capture=()=>{draft=draft.map((x,i)=>({name:document.querySelector(`#founder-name-${i}`).value,bio:document.querySelector(`#founder-bio-${i}`).value,photo:document.querySelector(`#founder-photo-${i}`).value,file:document.querySelector(`#founder-file-${i}`).files?.[0]||x.file,x:Number(document.querySelector(`#founder-x-${i}`).value),y:Number(document.querySelector(`#founder-y-${i}`).value),fit:document.querySelector(`#founder-fit-${i}`).value}));};const bindRows=()=>{draft.forEach((founder,i)=>{const preview=document.querySelector(`#founder-preview-${i}`);const adjust=()=>{preview.style.objectFit=document.querySelector(`#founder-fit-${i}`).value;preview.style.objectPosition=`${document.querySelector(`#founder-x-${i}`).value}% ${document.querySelector(`#founder-y-${i}`).value}%`;};['fit','x','y'].forEach(key=>document.querySelector(`#founder-${key}-${i}`).oninput=adjust);const file=document.querySelector(`#founder-file-${i}`);file.onchange=()=>{if(file.files[0]){if(preview.dataset.blob)URL.revokeObjectURL(preview.dataset.blob);const blob=URL.createObjectURL(file.files[0]);preview.dataset.blob=blob;preview.src=blob;preview.classList.remove('hidden');adjust();}};document.querySelector(`#founder-photo-${i}`).oninput=event=>{const url=safePortrait(event.target.value);if(url){preview.src=url;preview.classList.remove('hidden');adjust();}};if(founder.file){const blob=URL.createObjectURL(founder.file);preview.dataset.blob=blob;preview.src=blob;preview.classList.remove('hidden');}});document.querySelectorAll('[data-remove-founder]').forEach(button=>button.onclick=()=>{capture();draft.splice(Number(button.dataset.removeFounder),1);document.querySelector('#founder-fields').innerHTML=founderFields();bindRows();});};bindRows();document.querySelector('#add-founder').onclick=()=>{if(draft.length>=20){ui.toast('You can add up to 20 founder profiles.');return;}capture();draft.push({name:'',bio:'',photo:'',x:50,y:50,fit:'cover'});document.querySelector('#founder-fields').innerHTML=founderFields();bindRows();};form.onsubmit=async event=>{event.preventDefault();const submit=document.querySelector('#about-save'),status=document.querySelector('#about-status');submit.disabled=true;try{capture();const founders=[];for(let i=0;i<draft.length;i++){const founder={...draft[i],name:draft[i].name.trim()};if(!founder.name)throw new Error('Enter each founder’s full name.');const file=document.querySelector(`#founder-file-${i}`).files[0]||founder.file;if(file){status.textContent=`Uploading picture ${i+1}…`;founder.photo=await backend.uploadPortrait(file);}else if(founder.photo&&!safePortrait(founder.photo))throw new Error('Use an HTTPS picture URL.');founders.push(founder);}const contributors=document.querySelector('#about-contributors').value.split('\n').map(x=>x.trim()).filter(Boolean);if(contributors.length>200||contributors.some(x=>x.length>300))throw new Error('Use up to 200 contributor entries of 300 characters each.');const email=document.querySelector('#support-email').value.trim(),phone=document.querySelector('#support-phone').value.trim();if(email&&!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email))throw new Error('Enter a valid support email.');if(phone&&!/^\+?[0-9 ()-]{5,30}$/.test(phone))throw new Error('Enter a valid support phone number.');const next=normalizeAbout({support:{email,phone},mission:document.querySelector('#about-mission').value,founders,contributors});status.textContent='Publishing…';await backend.saveAbout(next);content=next;await ui.reload();ui.render();ui.toast('About LexAmah updated.');}catch(err){status.textContent=err.message;}finally{submit.disabled=false;}};}

export function supportSection(){const {email,phone}=content.support;const validEmail=/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email);const validPhone=/^\+?[0-9 ()-]{5,30}$/.test(phone);return `<section class="card" style="margin-top:24px"><h2>Contact & Support</h2><p class="muted">Questions about your account, materials or recordings? Reach the LexAmah team.</p><div class="actions">${validEmail?`<a class="btn primary" href="mailto:${e(email)}">${e(email)}</a>`:''}${validPhone?`<a class="btn" href="tel:${phone.replace(/[^0-9+]/g,'')}">${e(phone)}</a>`:''}${!validEmail&&!validPhone?'<p class="muted">Contact details will be added soon.</p>':''}</div></section>`;}
export function supportPage(){return `<div class="heading"><div><span class="eyebrow">WE’RE HERE TO HELP</span><h1>Contact & Support</h1></div></div>${supportSection()}`;}
